function verif() {
  const id = document.getElementById("id").value;
  const np = document.getElementById("np").value;
  const dn = document.getElementById("dn").value;
  const tel = document.getElementById("tel").value;

  //Id=======================================================
  if (id.length != 4 || id[0] != "E" || !numerique(id.substr(1))) {
    alert("Vérifier l'id");
    return false;
  }
  //Nom & Prenom=============================================
  if (np.length < 10 || !alpha(np)) {
    alert("Vérifier le nom et prénom");
    return false;
  }
  //Date naiss================================================
  if (dn == "") {
    alert("Vérifier date naissance");
    return false;
  }
  //Tel=====================================================
  if (tel.length != 8 || !numerique(tel)) {
    alert("Vérifier le num tel");
    return false;
  }
}
//==================================================================
function alpha(ch) {
  ch = ch.toUpperCase();
  const car = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ";
  for (let i = 0; i < ch.length; i++) {
    if (car.indexOf(ch[i]) < 0) {
      return false;
    }
  }
  return true;
}
//==================================================================
function numerique(ch) {
  const car = "0123456789";
  for (let i = 0; i < ch.length; i++) {
    if (car.indexOf(ch[i]) < 0) {
      return false;
    }
  }
  return true;
}

