function verif2() {
  const id = document.getElementById("id2").value;
  const np = document.getElementById("np2").value;

  if ((np != "" && id != "") || (np == "" && id == "")) {
    alert("veuillez respecter la saisie svp");
    return false;
  }

  if (
    id != "" &&
